    if (element.url) {
      return `Website: ${element.url.substring(0, 20)}${element.url.length > 20 ? "..." : ""}`;
    }
    if (element.src) {
      return `Image: ${element.src.substring(0, 20)}${element.src.length > 20 ? "..." : ""}`;
    }
    const typeName = element.type.charAt(0).toUpperCase() + element.type.slice(1);
